import{_ as a,a0 as n,w as u,s as p,ao as s,I as e,x as r,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"VirturalBox 终于进入到 5.0 世代 | LCTT x X-CMD","titleTemplate":false,"description":"VirturalBox 终于进入到 5.0 世代 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"VirturalBox 终于进入到 5.0 世代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"VirturalBox 终于进入到 5.0 世代 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150402 The VirtualBox 5.0 beta is finally here","title":"VirturalBox 终于进入到 5.0 世代","tag":"201504","desc":""},"relativePath":"201504/20150402 The VirtualBox 5.0 beta is finally here.md","filePath":"[post].md"}'),x={name:"201504/20150402 The VirtualBox 5.0 beta is finally here.md"};function f(d,t,m,V,T,B){const l=n("Link");return u(),p("div",null,[t[18]||(t[18]=s('<h1 id="virturalbox-终于进入到-5-0-世代" tabindex="-1">VirturalBox 终于进入到 5.0 世代 <a class="header-anchor" href="#virturalbox-终于进入到-5-0-世代" aria-label="Permalink to “VirturalBox 终于进入到 5.0 世代”">​</a></h1><p><strong>本月初，甲骨文公司的桌面虚拟化软件获得了近五年来的第一次重大改版，但是更像是改进而不是革命性的的变化。</strong></p><p>VirtualBox，由Sun公司创建，现在由甲骨文管理的开源虚拟化系统，获得了近5年来第一次的主版本更新发布。</p><p>从发行说明和测试版本身的表现来看，别期望任何真正革命性的改变。在此版本中，VirtualBox在视觉上和技术上都做了一些改进，但和VMware相比，它的主要优势仍然是相同核心功能的开源实现。</p><p>VirtualBox 4.0的最后一个主要版本在2010年12月发布，它采用了新的图形化用户界面，新的虚拟化硬件和重组的项目设计，进行了重大的改版。但项目主要版本的发布步伐缓慢，上一次重要版本(版本4.3)在2013年底才发布。从那时起，一切都被正式称为“维护”发布。</p><p><img src="http://images.techhive.com/images/article/2015/04/vbox-5-100576781-large.idge.png" alt=""></p><p><em>VirtualBox 5.0的第一个测试版增加了编辑菜单，VM窗口的快捷方式图标等功能，如下面所示。</em></p><p>VirtualBox 5.0最大的变化是增加了对硬件辅助虚拟化指令集扩展的支持。AES-NI指令集通常用于加密时的硬件加速，SSE 4.1和SSE 4.2指令集都包括在其中。另外一点是支持Windows和Linux客户机的半虚拟化，一个抽象主机音响设备的新的架构以及支持客户机中的USB 3（xHCI）控制器。</p><p>大部分可用性更新都是对 VirtualBox 图形化用户界面的改进。一个大的变化就是支持给单个虚拟主机自定义菜单和工具栏，这样很少或者从不使用的选项就可以彻底删除。另外重要的一点是可以在VirtualBox接口内部对虚拟磁盘进行加密，而不依赖于客户机操作系统自身的磁盘加密功能(假设有的话)。</p><p>甲骨文公司提醒由于这是个测试版软件，需要谨慎对待。当然，主界面和客户机系统界面的某个角落打着红黑相间的测试警告标志。但之前VirtualBox发行版(4.3.26)上创建的Windows 10虚拟机启动和运行都没问题，5.0版本中添加的VirtualBox客户机功能--更好的视频支持，双向复制和粘贴，以及其它功能--在安装的时候也没有问题。(从4.3.18版本就改进了对 Windows 10的支持)。</p>',10)),e("p",null,[t[2]||(t[2]=r("虽然没有明确指出5.0的最终版什么时候会发布，但是甲骨文公司",-1)),i(l,{href:"https://forums.virtualbox.org/viewtopic.php?f=15&t=66904"},{default:o(()=>[...t[0]||(t[0]=[r("建议用户",-1)])]),_:1}),t[3]||(t[3]=r("在非生产环境中下载和使用测试版，并在",-1)),i(l,{href:"https://forums.virtualbox.org/viewforum.php?f=15"},{default:o(()=>[...t[1]||(t[1]=[r("测试版反馈论坛",-1)])]),_:1}),t[4]||(t[4]=r("中提交bug报告。",-1))]),t[19]||(t[19]=e("hr",null,null,-1)),e("p",null,[t[6]||(t[6]=r("via: ",-1)),i(l,{href:"http://www.infoworld.com/article/2905098/virtualization/oracle-virtualbox-5-0-beta-is-finally-here.html"},{default:o(()=>[...t[5]||(t[5]=[r("http://www.infoworld.com/article/2905098/virtualization/oracle-virtualbox-5-0-beta-is-finally-here.html",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=r("作者：",-1)),i(l,{href:"http://www.infoworld.com/author/Serdar-Yegulalp/"},{default:o(()=>[...t[7]||(t[7]=[r("Serdar Yegulalp",-1)])]),_:1}),t[11]||(t[11]=r(" 译者：",-1)),i(l,{href:"https://github.com/ictlyh"},{default:o(()=>[...t[8]||(t[8]=[r("ictlyh",-1)])]),_:1}),t[12]||(t[12]=r(" 校对：",-1)),i(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=r("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[r("LCTT",-1)])]),_:1}),t[16]||(t[16]=r(" 原创翻译，",-1)),i(l,{href:"http://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[r("Linux中国",-1)])]),_:1}),t[17]||(t[17]=r(" 荣誉推出",-1))])])}const C=a(x,[["render",f]]);export{b as __pageData,C as default};
